using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;

namespace AkilliKisayol {
 public sealed class MacroWindow : Window {
  readonly Binding old;readonly KeyboardEngine engine;readonly bool paused;readonly MacroRecorder recorder;readonly List<Binding> existing;readonly Func<IEnumerable<SystemShortcut>> external;
  readonly TextBox name=new TextBox{Text="New macro"},trigger=new TextBox{Text="F8"};readonly ListBox list=new ListBox{MinHeight=200};readonly TextBlock status=Theme.Text("",13,"Muted");readonly Button record,save;
  readonly ComboBox profile=new ComboBox();readonly CheckBox enabled=new CheckBox{Content="Shortcut active",IsChecked=true};readonly string currentProfile;List<ActionStep> steps=new List<ActionStep>();bool closing,finishing;public Binding Result;
  public MacroWindow(KeyboardEngine keyboard,IEnumerable<Binding> bindings,IEnumerable<ShortcutProfile> profiles,string activeProfile,Func<IEnumerable<SystemShortcut>> externalSources,Binding previous=null,bool actionOnly=false){
   old=previous;currentProfile=activeProfile;enabled.IsChecked=previous==null||previous.Enabled;engine=keyboard;paused=engine.Paused;engine.Paused=true;engine.ResetPending();Actions.CancelWorkflow();existing=bindings.ToList();external=externalSources??(()=>new SystemShortcut[0]);recorder=new MacroRecorder(engine);recorder.StopRequested+=()=>{if(!closing&&!finishing)StopRecord();};recorder.Changed+=()=>{if(!closing&&recorder.Recording){list.ItemsSource=recorder.Steps.Select((s,i)=>(i+1)+". "+s.Summary).ToList();status.Text="● Recording active • "+recorder.Steps.Count+" step • Finish with F10";}};
   Style=(Style)Application.Current.FindResource(typeof(Window));Title="Macro recorder";Width=900;Height=800;MinWidth=720;MinHeight=640;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);
   var dock=new DockPanel{Margin=new Thickness(26)};Content=dock;var bottom=new StackPanel();bottom.Children.Add(new ScrollViewer{Content=status,MaxHeight=120,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};buttons.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));save=Theme.Button("Save macro",Commit,true);save.IsEnabled=false;buttons.Children.Add(save);bottom.Children.Add(buttons);DockPanel.SetDock(bottom,Dock.Bottom);dock.Children.Add(bottom);
   var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text("Show operation once",27));form.Children.Add(Theme.Text("Start recording, switch to the target application, and perform your operation. F10 ends the recording. This application's own windows and synthetic inputs are not recorded. Personal shortcuts do not work during recording.",13,"Muted"));Label(form,"Macro name");form.Children.Add(name);Label(form,"Run key");var keyRow=new DockPanel();var capture=Theme.Button("Press key",Capture);DockPanel.SetDock(capture,Dock.Right);keyRow.Children.Add(capture);keyRow.Children.Add(trigger);keyRow.Visibility=actionOnly?Visibility.Collapsed:Visibility.Visible;form.Children.Add(keyRow);Label(form,"Profile");profile.DisplayMemberPath="Name";profile.SelectedValuePath="Id";profile.ItemsSource=new[]{new ShortcutProfile{Id="",Name="All profiles"}}.Concat(profiles).ToList();profile.SelectedValue=previous!=null?previous.ProfileId??"":activeProfile;form.Children.Add(profile);enabled.Margin=new Thickness(0,10,0,0);form.Children.Add(enabled);enabled.Checked+=(s,e)=>Refresh();enabled.Unchecked+=(s,e)=>Refresh();
   var bar=new WrapPanel{Margin=new Thickness(0,18,0,12)};record=Theme.Button("● Start recording",StartRecord,true);bar.Children.Add(record);bar.Children.Add(Theme.Button("Finish recording (F10)",()=>StopRecord()));bar.Children.Add(Theme.Button("Remove selected step",()=>{if(recorder.Recording||finishing)return;int index=list.SelectedIndex;if(index>=0){steps.RemoveAt(index);Refresh();}}));form.Children.Add(bar);var edits=new WrapPanel{Margin=new Thickness(0,0,0,12)};edits.Children.Add(Theme.Button("Add step",()=>EditStep(true)));edits.Children.Add(Theme.Button("Edit step",()=>EditStep(false)));edits.Children.Add(Theme.Button("Up",()=>MoveStep(-1)));edits.Children.Add(Theme.Button("Down",()=>MoveStep(1)));edits.Children.Add(Theme.Button("Duplicate",()=>{if(recorder.Recording||finishing)return;int i=list.SelectedIndex;if(i>=0&&steps.Count<500){steps.Insert(i+1,steps[i].Copy());Refresh();list.SelectedIndex=i+1;}}));form.Children.Add(edits);form.Children.Add(list);list.MouseDoubleClick+=(s,e)=>EditStep(false);
   form.Children.Add(Theme.Text("Left-clicks on items that can be found are played over the item. Other clicks, drags, and scrolls use the window-relative position; if the window size changes, the macro stops. Keyboard recording saves physical keys and AltGr information; use the same keyboard layout. Target applications must be open during playback. Escape cancels the remaining steps.",12,"Muted"));
   foreach(var box in new[]{name,trigger})box.TextChanged+=(s,e)=>Refresh();profile.SelectionChanged+=(s,e)=>Refresh();Closed+=(s,e)=>{closing=true;recorder.Dispose();engine.Capture=null;engine.ResetPending();engine.Paused=paused;};Deactivated+=(s,e)=>{if(!recorder.Recording)engine.Capture=null;};if(previous!=null){name.Text=previous.Name;trigger.Text=TriggerSpec.Format(previous.Mods,previous.Key,previous.PrefixKey);steps=(previous.Steps??new List<ActionStep>()).Select(s=>s.Copy()).ToList();}Refresh();
  }
  static void Label(StackPanel form,string text){var label=Theme.Text(text,13);label.Margin=new Thickness(0,13,0,7);form.Children.Add(label);}
  void StartRecord(){if(finishing||recorder.Recording)return;try{engine.Capture=null;recorder.Start();steps.Clear();record.IsEnabled=false;save.IsEnabled=false;name.IsEnabled=trigger.IsEnabled=profile.IsEnabled=enabled.IsEnabled=false;status.Text="● Recording active. Switch to target application; finish with F10.";list.ItemsSource=null;}catch(Exception e){status.Text=e.Message;}}
  async void StopRecord(){await StopAsync();}
  async Task StopAsync(){if(!recorder.Recording||finishing)return;finishing=true;record.IsEnabled=false;try{steps=await recorder.StopAsync();if(closing)return;if(recorder.Error.Length>0){steps.Clear();status.Text="Record could not be completed: "+recorder.Error;}else Refresh();}finally{finishing=false;if(!closing){record.IsEnabled=true;name.IsEnabled=trigger.IsEnabled=profile.IsEnabled=enabled.IsEnabled=true;Refresh(recorder.Error.Length>0?"Record could not be completed: "+recorder.Error:null);}}}
  void EditStep(bool add){if(recorder.Recording||finishing)return;int i=list.SelectedIndex;if(!add&&i<0)return;var editor=new StepEditor(add?null:steps[i]){Owner=this};if(editor.ShowDialog()!=true)return;if(add)steps.Add(editor.Result);else steps[i]=editor.Result;Refresh();list.SelectedIndex=add?steps.Count-1:i;}
  void MoveStep(int direction){if(recorder.Recording||finishing)return;int i=list.SelectedIndex,j=i+direction;if(i<0||j<0||j>=steps.Count)return;var step=steps[i];steps.RemoveAt(i);steps.Insert(j,step);Refresh();list.SelectedIndex=j;}
  void Capture(){if(recorder.Recording||finishing)return;engine.Capture=(mods,key,prefix,altgr)=>{engine.Capture=null;if(key==27)return;if(altgr){status.Text="Use Left Alt instead of AltGr for the shortcut.";return;}trigger.Text=TriggerSpec.Format(mods,key,prefix);};}
  Binding Draft(){TriggerSpec gesture=new TriggerSpec();if((old==null||old.Gesture==null)&&!TriggerSpec.TryParse(trigger.Text,out gesture))throw new ArgumentException("Select the button that will run the macro.");return new Binding{Id=old!=null?old.Id:Guid.NewGuid().ToString(),Enabled=enabled.IsChecked==true,Name=name.Text.Trim(),Key=gesture.Key,Mods=gesture.Mods,PrefixKey=gesture.Prefix,Kind="Workflow",IsMacro=true,AppPath=old==null?"":old.AppPath,Prompt=old==null?null:old.Prompt,Gesture=old==null||old.Gesture==null?null:old.Gesture.Copy(),Steps=steps.Select(s=>s.Copy()).ToList(),ProfileId=profile.SelectedValue as string??""};}
  void Refresh(string message=null){if(closing||save==null||recorder.Recording)return;list.ItemsSource=steps.Select((s,i)=>(i+1)+". "+s.Summary+(string.IsNullOrEmpty(s.AppPath)?"":" • "+AppLibrary.Name(s.AppPath))).ToList();try{var draft=Draft();string error=steps.Any(s=>s.Kind!="Focus"&&s.Kind!="Wait")?Rules.Validate(draft,existing):"First, save an action.";var warnings=Rules.Conflicts(draft,existing);warnings.AddRange(ShortcutConflicts.ForBinding(draft,external()));status.Text=message??error??Profiles.Describe(draft,profile.Items.Cast<ShortcutProfile>(),currentProfile,paused)+"\n"+(warnings.Count>0?string.Join("\n",warnings):steps.Count+" step ready. Playback does not start without saving.");save.IsEnabled=error==null&&!finishing;}catch(ArgumentException e){status.Text=message??e.Message;save.IsEnabled=false;}}
  void Commit(){if(recorder.Recording||finishing)return;try{var draft=Draft();string error=Rules.Validate(draft,existing);if(error!=null){status.Text=error;return;}Result=draft;DialogResult=true;}catch(Exception e){status.Text=e.Message;}}
  internal void StepsForTest(IEnumerable<ActionStep> value){steps=value.Select(s=>s.Copy()).ToList();Refresh();}
  internal void EnabledForTest(bool value){enabled.IsChecked=value;}
  internal Binding DraftForTest(){return Draft();}
  internal void SaveForTest(){Commit();}
  internal bool CanSaveForTest {get{return save.IsEnabled;}}
 }
}
